137	        const created = await userServiceClient.createUserWebhook({
138	          parent: currentUser.name,
139	          webhook: { displayName: state.displayName, url: state.url },
140	        });
141	        let secret: string | undefined;
142	        try {
143	          const response = await userServiceClient.getUserWebhookSigningSecret({ name: created.name });
144	          secret = response.signingSecret;
145	        } catch {
146	          // Reveal failed — the secret is still set and can be revealed later from the edit dialog.
147	        }
148	        requestState.setFinish();
149	        if (secret !== undefined) {
150	          setCreatedSecret(secret);
151	          return;
152	        }
153	        onSuccess?.();
154	        onOpenChange(false);
155	        return;
156	      }
157	
158	      await userServiceClient.updateUserWebhook({
159	        webhook: { name: webhookName, displayName: state.displayName, url: state.url },
