187	
188	  const renderSigningSecret = () => {
189	    if (isCreating) {
190	      return <span className="text-xs text-muted-foreground">{t("setting.webhook.create-dialog.signing-secret-auto-note")}</span>;
191	    }
192	    if (revealedSecret !== undefined) {
193	      return renderSecretField(revealedSecret);
194	    }
