210	          {t("setting.webhook.create-dialog.generate-secret")}
211	        </Button>
212	      </div>
213	    );
214	  };
215	
216	  return (
217	    <Dialog open={open} onOpenChange={handleOpenChange}>
218	      <DialogContent className="max-w-md">
219	        <DialogHeader>
220	          <DialogTitle>
221	            {isCreating ? t("setting.webhook.create-dialog.create-webhook") : t("setting.webhook.create-dialog.edit-webhook")}
222	          </DialogTitle>
223	        </DialogHeader>
224	        {createdSecret !== undefined ? (
